def gen(rng):
    LIM = 5000

    def make(n, mode, vr):
        val = [rng.randint(-vr, vr) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        dep = [1] * n
        slots = [(0, 0), (0, 1)] if LIM > 1 else []

        def pick_random():
            while True:
                k = rng.randrange(len(slots))
                node, side = slots[k]
                slots[k] = slots[-1]
                slots.pop()
                if (L if side == 0 else R)[node] == -1:
                    return node, side

        for i in range(1, n):
            side_pref = 0 if mode == 'left' else 1 if mode == 'right' else (i % 2)
            if mode in ('left', 'right', 'zig') and dep[i - 1] < LIM:
                node, side = i - 1, side_pref
            else:
                node, side = pick_random()
            if side == 0:
                L[node] = i
            else:
                R[node] = i
            dep[i] = dep[node] + 1
            if dep[i] < LIM:
                slots.append((i, 0))
                slots.append((i, 1))
        out = [str(val[0])]
        q = [0]
        h = 0
        while h < len(q):
            x = q[h]
            h += 1
            for c in (L[x], R[x]):
                if c == -1:
                    out.append('null')
                else:
                    out.append(str(val[c]))
                    q.append(c)
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    tests = ['0', '-7', '1 2', '1 null 2', '1 2 3', '1 2 3 4 5 6 7', '1 null 2 null 3 null 4', '5 4 null 3 null 2 null 1']
    for _ in range(14):
        tests.append(make(rng.randint(1, 10), rng.choice(('rand', 'rand', 'left', 'right', 'zig')), rng.choice((5, 100))))
    tests.append(make(5000, 'left', 1000))
    tests.append(make(5000, 'right', 1000))
    tests.append(make(5000, 'zig', 1000))
    tests.append(make(50000, 'rand', 1000))
    tests.append(make(50000, 'left', 1000))
    tests.append(make(50000, 'zig', 1000))
    return tests
